parameters.responseBody:
={{ (() => {
  const b = $('DeployX Deploy Request').first().json.body;
  const ctx = ($('Resolve Deploy User').first().json || {}).context || {};
  const rawStatus = $('Get Vercel Deployment Status').last().json || {};
  const d = rawStatus.deployment || rawStatus;
  const requested = String(b.github_repository || '');
  const repo = requested.includes('/') ? requested.split('/')[1] : (requested || b.project_name);
  const fullName = ctx.github_username + '/' + repo;
  const host = (d.alias && d.alias.length) ? d.alias[0] : d.url;
  const required = Array.isArray(b.env_var_names) ? b.env_var_names.map(String).filter(k => k) : [];
  let envSrc = {};
  try { envSrc = ($('Get Vercel Env Var Names').first() || {}).json || {}; } catch (e) { envSrc = {}; }
  const envNames = Array.isArray(envSrc.env_var_names) ? envSrc.env_var_names.map(String) : null;
  const warnings = [];
  let env_check;
  let missing = [];
  if (required.length === 0) {
    env_check = 'not_requested';
  } else if (!envNames) {
    env_check = 'check_failed';
    warnings.push('Could not read environment variable names from your Vercel project, so required variables were not checked.');
  } else {
    const inProd = new Set(envNames);
    missing = required.filter(k => !inProd.has(k));
    env_check = missing.length ? 'missing' : 'ok';
    if (missing.length) {
      warnings.push('Missing on Vercel: ' + missing.join(', ') + '. Add them in Vercel > Project > Settings > Environment Variables, then redeploy.');
    }
  }
  return JSON.stringify({
    success: true,
    deployment_id: b.deployment_id ?? null,
    project_name: b.project_name,
    framework: b.framework ?? null,
    github_username: ctx.github_username,
    github_repository: fullName,
    github_url: 'https://github.com/' + fullName,
    vercel_url: host ? 'https://' + host : null,
    vercel_deployment_id: d.id,
    vercel_project_settings_url: null,
    env_check: env_check,
    required_env_vars: required,
    missing_env_vars: missing,
    warnings: warnings
  });
})() }}

parameters.jsonOutput:
={{ (() => {
  const b = $('DeployX Deploy Request').first().json.body || {};
  let ctx = {};
  if ($('Resolve Deploy User').isExecuted) {
    try { ctx = (($('Resolve Deploy User').first(0, 0) || {}).json || {}).context || {}; } catch (e) { ctx = {}; }
  }
  const redact = s => String(s || '').replace(/(gh[pousr]_[A-Za-z0-9]{10,}|github_pat_[A-Za-z0-9_]{10,})/g, '[redacted]').replace(/Bearer +[^ "']+/gi, 'Bearer [redacted]').replace(/[A-Za-z0-9_-]{40,}/g, '[redacted]').slice(0, 1500);
  const src = $prevNode.name;
  const apiErr = $json['error'];
  const apiMsg = apiErr ? redact(apiErr.description || apiErr.message || JSON.stringify(apiErr)) : '';
  // The backend reports the real reason in an `error` code. Never guess an
  // authentication problem when the backend said something else.
  const code = String($json.code || $json.error_code || (typeof $json.error === 'string' ? $json.error : '') || '').trim();
  const authCodes = ['invalid_ticket', 'ticket_expired', 'ticket_used', 'unauthorized', 'provider_not_connected'];
  const isAuth = authCodes.indexOf(code) !== -1;
  let failure_stage, error;
  let auth_required = false;
  if (src === 'Git Push Confirmed?') {
    failure_stage = 'push_not_confirmed';
    error = 'Git push was not confirmed by DeployX CLI (git_push_confirmed must be true and project_name is required). Vercel deployment was not started.';
  } else if (src === 'Resolve Deploy User') {
    if (isAuth) {
      failure_stage = 'authorization';
      auth_required = true;
      error = 'DeployX backend rejected the deployment ticket or provider connection (' + code + '). ' + apiMsg;
    } else {
      failure_stage = code ? 'backend_error' : 'backend_unreachable';
      error = 'DeployX backend call failed' + (code ? ' (' + code + ')' : '') + ': ' + (apiMsg || 'no response from the backend. Check that it is running and reachable from n8n.');
    }
  } else if (src === 'Repository Belongs to User?') {
    failure_stage = 'identity_mismatch';
    error = 'The requested repository does not belong to the authenticated DeployX user. Deployment stopped.';
  } else if (apiErr) {
    failure_stage = 'vercel_api';
    error = 'Vercel API error: ' + apiMsg;
  } else if (['ERROR', 'CANCELED', 'BLOCKED'].includes($json['ready_state'])) {
    failure_stage = 'vercel_build';
    error = 'Vercel build ended with state ' + $json['ready_state'] + ($json['error_message'] ? ': ' + redact($json['error_message']) : '');
  } else {
    failure_stage = 'vercel_timeout';
    error = 'Timed out waiting for Vercel build (last state: ' + ($json['ready_state'] || 'unknown') + '). Deployment ID: ' + (($json['deployment'] || {}).id || 'unknown');
  }
  const requested = String(b.github_repository || '');
  const repo = requested.includes('/') ? requested.split('/')[1] : (requested || b.project_name || '');
  const owner = ctx.github_username || null;
  return JSON.stringify({
    deployment_id: b.deployment_id ?? null,
    project_name: b.project_name ?? null,
    framework: b.framework ?? null,
    branch: b.branch || 'main',
    github_username: owner,
    github_url: (owner && repo) ? 'https://github.com/' + owner + '/' + repo : null,
    failure_stage: failure_stage,
    auth_required: auth_required,
    error: error,
    vercel_deployment_id: $json['id'] ?? null,
    vercel_error_code: $json['errorCode'] ?? null
  });
})() }}

