// Count status polls for this deployment ticket so the Vercel polling
// window (36 checks x 10s = 6 minutes) can never run indefinitely.
// The counter is scoped per deployment ticket, so two concurrent
// deployments never share state.
const store = $getWorkflowStaticData('global');
const body = $('DeployX Deploy Request').first().json.body || {};
const key = String(body.deployment_ticket || body.deployment_id || 'unknown');
const max = Number($('Load Deploy Config').first().json.max_status_checks || 36);

store.deployx_status_checks = store.deployx_status_checks || {};
const checks = Number(store.deployx_status_checks[key] || 0) + 1;
store.deployx_status_checks[key] = checks;

const status = $json || {};
const deployment = status.deployment || {};

return [{
  json: {
    ...status,
    status_checks: checks,
    max_status_checks: max,
    ready_state: deployment.ready_state ?? status.ready_state ?? null,
    ticket_closed: status.ticket_closed ?? false,
    deployment
  }
}];
